-- ============================================================
-- PROJETO SURFLO
-- Sistema de Gestão de Competições de Surf e Conservação Marinha
-- ============================================================
--
-- ARQUIVO: 02_insertion_donnees_SURFLO.sql
-- OBJETIVO:
-- Inserir os dados de teste na base de dados SURFLO,
-- previamente criada através do script 01_criacao_bdd_SURFLO.sql.
--
-- CONTEÚDO DOS DADOS:
--   - 1 campeonato
--   - 5 etapas em praias diferentes
--   - 5 categorias de competição
--   - 80 atletas
--   - 400 inscrições
--   - 175 baterias
--   - 700 participações em baterias
--   - 2.800 avaliações realizadas pelos juízes
--
-- OUTROS DADOS:
--   - Juízes e responsáveis pelas praias
--   - Resultados das baterias e das etapas
--   - Classificação geral e premiações
--   - Ingressos e clientes
--   - Patrocinadores e contratos
--   - Autorizações e ações ambientais
--
-- ============================================================

PRAGMA foreign_keys = ON;
