INSERT INTO CLASSIFICACAO_GERAL
(id_campeonato,id_categoria,id_atleta,pontuacao_total,quantidade_resultados_contabilizados,posicao_geral)
SELECT id_campeonato,id_categoria,id_atleta,pontuacao_total,
       quantidade_resultados_contabilizados,posicao_geral
FROM VW_CLASSIFICACAO_GERAL_CALCULADA;

INSERT INTO ATRIBUICAO_PREMIACAO(id_premiacao,id_classificacao_geral)
SELECT p.id_premiacao,c.id_classificacao_geral
FROM CLASSIFICACAO_GERAL c
JOIN CATEGORIA cat ON cat.id_categoria=c.id_categoria
JOIN PREMIACAO p ON p.familia_categoria=cat.familia_premiacao
                AND p.posicao_geral=c.posicao_geral;

COMMIT;
